fn main() {
    let grades = BTreeMap::from([("A", 90), ("B", 80), ("C", 70)]);
}

exercises.solution:
use std::collections::BTreeMap;

fn main() {
    let grades = BTreeMap::from([("A", 90), ("B", 80), ("C", 70)]);
    for (k, v) in &grades {
        println!("{} {}", k, v);
    }
}
